import type { StateStorage, PersistStorage, StorageValue } from "zustand/middleware";

// Detect whether we're running inside the Tauri native shell.
// When running with `npm run dev` (browser-only), Tauri APIs are absent
// and we fall back to localStorage so dev-mode still works.
function isTauri(): boolean {
  return typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;
}

// Lazy singleton — one Store instance for the app lifetime.
let _store: import("@tauri-apps/plugin-store").Store | null = null;

async function getStore(): Promise<import("@tauri-apps/plugin-store").Store> {
  if (!_store) {
    const { load } = await import("@tauri-apps/plugin-store");
    _store = await load("app-state.json");
  }
  return _store;
}

// #3612: throttle the expensive full-file fsync. Zustand's `persist` calls setItem after EVERY store
// `set()`, and under the Design Studio's per-component scan that is hundreds of writes in a burst. The
// in-memory value is updated immediately on each write (cheap), but `store.save()` — which flushes the
// whole file to disk — is throttled to at most once per SAVE_THROTTLE_MS, always flushing the LATEST
// value. A trailing timer that is never reset while pending means continuous writes still flush every
// interval rather than starving. Worst case on a hard crash: the last <SAVE_THROTTLE_MS of state isn't
// flushed — which crash recovery already tolerates.
const SAVE_THROTTLE_MS = 250;
let saveTimer: ReturnType<typeof setTimeout> | null = null;

function scheduleSave(store: import("@tauri-apps/plugin-store").Store): void {
  if (saveTimer) return; // a flush is already pending; it will capture the latest in-memory value
  saveTimer = setTimeout(() => {
    saveTimer = null;
    void store.save();
  }, SAVE_THROTTLE_MS);
}

export const persistStorage: StateStorage = {
  getItem: async (name) => {
    if (!isTauri()) return localStorage.getItem(name);
    const store = await getStore();
    return (await store.get<string>(name)) ?? null;
  },

  setItem: async (name, value) => {
    if (!isTauri()) { localStorage.setItem(name, value); return; }
    const store = await getStore();
    await store.set(name, value); // update the in-memory value immediately (cheap)
    scheduleSave(store);          // throttle the expensive disk flush (#3612)
  },

  removeItem: async (name) => {
    if (!isTauri()) { localStorage.removeItem(name); return; }
    if (saveTimer) { clearTimeout(saveTimer); saveTimer = null; } // supersede any pending throttled save
    const store = await getStore();
    await store.delete(name);
    await store.save();
  },
};


// ── The SERIALIZATION throttle (#every-store-write-restringifies-the-whole-persisted-snapshot) ──────

/** How long serializations are coalesced. Mirrors [`SAVE_THROTTLE_MS`] — the two halves of one write
 *  should not drift apart, and a lost window costs the same thing in both: <250ms of state on a hard
 *  crash, which crash recovery already tolerates. */
export const SERIALIZE_THROTTLE_MS = 250;

/**
 * A `PersistStorage` that throttles the SERIALIZATION, not merely the disk write.
 *
 * WHY THIS REPLACES `createJSONStorage`. That helper is where the cost lives — zustand's
 * `middleware.js`:
 *
 *     setItem: (name, newValue) => storage.setItem(name, JSON.stringify(newValue, …))
 *
 * and `persist` calls it on EVERY store `set()`, without checking whether any PERSISTED field
 * changed. The partialized snapshot is ~125 fields / ~129 KB, so a write to a high-frequency
 * NON-persisted field — `liveAgents`, `paneStatus`, `activeDebugRequests`, `paneLastActivity` — paid a
 * full partialize plus stringify. Measured in one 2-second window: `tabs x76, paneStatus x76`.
 *
 * ATTRIBUTED BY NATIVE STACK, after four wrong hypotheses: the renderer's main thread sat in
 * `WTF::StringBuilder::appendQuotedJSONString` in every sample, while RSS went 77 MB -> 6.4 GB in
 * nineteen seconds.
 *
 * The existing [`SAVE_THROTTLE_MS`] flush throttle could not help: it sits DOWNSTREAM and receives an
 * already-serialized string, so it saved I/O and nothing else. This is the same idea applied one layer
 * up, where the cost actually is.
 *
 * COALESCE, NEVER DROP. Only the newest state is kept, and a trailing flush always runs — so the final
 * write reaches disk even if it arrives in the middle of a window. Dropping it would make the store
 * silently lose the last change, which is worse than the cost this removes.
 */
export function throttledJSONStorage<S>(
  inner: StateStorage,
  ms: number = SERIALIZE_THROTTLE_MS,
): PersistStorage<S> {
  let pending: { name: string; value: StorageValue<S> } | null = null;
  let timer: ReturnType<typeof setTimeout> | null = null;

  const flush = (): void => {
    timer = null;
    const p = pending;
    pending = null;
    if (!p) return;
    // A DEFERRED WRITE CAN OUTLIVE ITS CONTEXT, and must not throw when it does. Throttling means the
    // flush fires up to `ms` after the write that scheduled it, by which point the storage backend may
    // be gone — a torn-down jsdom (`localStorage is not defined`, which the suite caught), a closing
    // window, a revoked Tauri store. A throw inside a `setTimeout` has no caller to catch it: it
    // becomes an unhandled error and reaches the crash overlay, so a failed persist would look like an
    // application crash.
    //
    // Both halves are needed: `setItem` can throw SYNCHRONOUSLY (localStorage) or reject
    // asynchronously (the Tauri store), and `void` alone catches neither.
    try {
      void Promise.resolve(inner.setItem(p.name, JSON.stringify(p.value))).catch(() => {
        /* the backend is gone; the next flush will carry the latest state anyway */
      });
    } catch {
      /* same, for a synchronous throw */
    }
  };

  return {
    getItem: async (name) => {
      const raw = await inner.getItem(name);
      return raw ? (JSON.parse(raw) as StorageValue<S>) : null;
    },
    setItem: (name, value) => {
      // Holding the OBJECT is what makes this cheap: no work happens until the window closes.
      pending = { name, value };
      if (!timer) timer = setTimeout(flush, ms);
    },
    removeItem: async (name) => {
      // A pending write must not resurrect what was just removed.
      if (timer) { clearTimeout(timer); timer = null; }
      pending = null;
      await inner.removeItem(name);
    },
  };
}

