/**
 * @vitest-environment jsdom
 *
 * This file lives under `lib/`, which vitest's `node` project covers, but it genuinely needs a DOM.
 * A per-file docblock beats the project's environment, so the requirement is stated where a reader
 * meets it. See the `projects` split in vitest.config.ts for why the default is `node` here.
 */
import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { load } from "@tauri-apps/plugin-store";
import { persistStorage, throttledJSONStorage } from "@/shared/lib/core/storage";

// persistStorage falls back to localStorage when not inside Tauri (jsdom env)

beforeEach(() => {
  localStorage.clear();
});

describe("persistStorage (localStorage fallback)", () => {
  it("setItem stores a value", async () => {
    await persistStorage.setItem("key", "value");
    expect(localStorage.getItem("key")).toBe("value");
  });

  it("getItem retrieves a stored value", async () => {
    localStorage.setItem("key", "hello");
    const result = await persistStorage.getItem("key");
    expect(result).toBe("hello");
  });

  it("getItem returns null for a missing key", async () => {
    const result = await persistStorage.getItem("nonexistent");
    expect(result).toBeNull();
  });

  it("removeItem deletes a stored value", async () => {
    localStorage.setItem("key", "to-remove");
    await persistStorage.removeItem("key");
    expect(localStorage.getItem("key")).toBeNull();
  });

  it("setItem overwrites an existing value", async () => {
    await persistStorage.setItem("key", "first");
    await persistStorage.setItem("key", "second");
    const result = await persistStorage.getItem("key");
    expect(result).toBe("second");
  });
});

// #3612 — inside Tauri, the expensive full-file fsync (store.save) is THROTTLED: a burst of store writes
// (e.g. the Design Studio's per-component scan, hundreds of setItem calls) flushes once per window, not
// once per write, while the in-memory value still updates on every write.
const win = window as unknown as { __TAURI_INTERNALS__?: unknown };

describe("persistStorage — throttled save (#3612)", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    win.__TAURI_INTERNALS__ = {}; // force isTauri() true → the plugin-store path (not the localStorage fallback)
  });
  afterEach(() => {
    vi.runOnlyPendingTimers();
    vi.useRealTimers();
    delete win.__TAURI_INTERNALS__;
  });

  it("coalesces a burst of writes into ONE disk save; each write still updates memory", async () => {
    const store = await load("app-state.json");
    vi.mocked(store.set).mockClear();
    vi.mocked(store.save).mockClear();

    await persistStorage.setItem("app-state", "v1");
    await persistStorage.setItem("app-state", "v2");
    await persistStorage.setItem("app-state", "v3");

    expect(store.set).toHaveBeenCalledTimes(3);   // in-memory value updated on EVERY write (cheap)
    expect(store.save).toHaveBeenCalledTimes(0);  // ...but the fsync is throttled — none fired yet

    await vi.advanceTimersByTimeAsync(300);        // past SAVE_THROTTLE_MS (250)
    expect(store.save).toHaveBeenCalledTimes(1);   // exactly ONE flush for the whole burst
  });

  it("is a throttle, not one-shot: a later write schedules a fresh flush", async () => {
    const store = await load("app-state.json");
    vi.mocked(store.save).mockClear();

    await persistStorage.setItem("app-state", "a");
    await vi.advanceTimersByTimeAsync(300);
    expect(store.save).toHaveBeenCalledTimes(1);

    await persistStorage.setItem("app-state", "b");
    await vi.advanceTimersByTimeAsync(300);
    expect(store.save).toHaveBeenCalledTimes(2);
  });
});

// The SERIALIZATION throttle (#every-store-write-restringifies-the-whole-persisted-snapshot).
//
// `createJSONStorage` stringifies the whole ~129 KB partialized snapshot on EVERY store `set()`,
// including writes to fields that are not persisted at all. A native stack caught the renderer's main
// thread in `appendQuotedJSONString` while RSS went 77 MB to 6.4 GB in nineteen seconds.
describe("throttledJSONStorage", () => {
  const flushable = () => {
    const calls: string[] = [];
    const inner = {
      getItem: vi.fn(async () => null),
      setItem: vi.fn(async (_n: string, v: string) => { calls.push(v); }),
      removeItem: vi.fn(async () => {}),
    };
    return { inner, calls };
  };

  beforeEach(() => vi.useFakeTimers());
  afterEach(() => vi.useRealTimers());

  it("serializes ONCE for a burst of writes, not once per write", () => {
    const { inner, calls } = flushable();
    const s = throttledJSONStorage<{ n: number }>(inner, 250);
    for (let i = 0; i < 500; i++) s.setItem("app-state", { state: { n: i }, version: 1 });

    // Nothing serialized yet — the whole point is that no work happens per write.
    expect(inner.setItem).not.toHaveBeenCalled();
    vi.advanceTimersByTime(250);
    expect(inner.setItem).toHaveBeenCalledTimes(1);
    // …and it is the LATEST state, not the first. Coalescing must never mean "keep the stale one".
    expect(JSON.parse(calls[0]).state.n).toBe(499);
  });

  it("always flushes the LAST write — coalescing must not drop it", () => {
    const { inner, calls } = flushable();
    const s = throttledJSONStorage<{ n: number }>(inner, 250);
    s.setItem("app-state", { state: { n: 1 }, version: 1 });
    vi.advanceTimersByTime(250);
    // A write arriving after the window still gets its own flush.
    s.setItem("app-state", { state: { n: 2 }, version: 1 });
    vi.advanceTimersByTime(250);
    expect(inner.setItem).toHaveBeenCalledTimes(2);
    expect(JSON.parse(calls[1]).state.n).toBe(2);
  });

  it("round-trips through getItem", async () => {
    const inner = {
      getItem: vi.fn(async () => JSON.stringify({ state: { n: 7 }, version: 3 })),
      setItem: vi.fn(async () => {}),
      removeItem: vi.fn(async () => {}),
    };
    const s = throttledJSONStorage<{ n: number }>(inner, 250);
    await expect(s.getItem("app-state")).resolves.toEqual({ state: { n: 7 }, version: 3 });

    inner.getItem.mockResolvedValueOnce(null as never);
    await expect(s.getItem("app-state")).resolves.toBeNull();
  });

  it("a removal cancels a pending write, so it cannot resurrect what was removed", async () => {
    const { inner } = flushable();
    const s = throttledJSONStorage<{ n: number }>(inner, 250);
    s.setItem("app-state", { state: { n: 1 }, version: 1 });
    await s.removeItem("app-state");
    vi.advanceTimersByTime(1000);
    expect(inner.setItem).not.toHaveBeenCalled();
    expect(inner.removeItem).toHaveBeenCalledWith("app-state");
  });

  it("a flush that outlives its storage does not throw", async () => {
    // Throttling means the flush fires up to `ms` after the write that scheduled it, by which point
    // the backend may be gone — a torn-down jsdom, a closing window. A throw inside a setTimeout has
    // no caller, so it becomes an unhandled error and reaches the crash overlay.
    const sync = { getItem: vi.fn(async () => null),
      setItem: vi.fn(() => { throw new ReferenceError("localStorage is not defined"); }),
      removeItem: vi.fn(async () => {}) };
    const a = throttledJSONStorage<{ n: number }>(sync as never, 250);
    a.setItem("app-state", { state: { n: 1 }, version: 1 });
    expect(() => vi.advanceTimersByTime(250)).not.toThrow();

    const async_ = { getItem: vi.fn(async () => null),
      setItem: vi.fn(async () => { throw new Error("store revoked"); }),
      removeItem: vi.fn(async () => {}) };
    const b = throttledJSONStorage<{ n: number }>(async_ as never, 250);
    b.setItem("app-state", { state: { n: 1 }, version: 1 });
    expect(() => vi.advanceTimersByTime(250)).not.toThrow();
    await Promise.resolve();
  });
});
